sp_widget.client_script:
api.controller = function($scope) {

    var c = this;


    // =====================================
    // RAISE TICKET
    // =====================================

    c.raiseTicket = function() {

        window.location.href =
            "?id=raise_ticket";

    };


    // =====================================
    // TICKET HISTORY
    // =====================================

    c.viewHistory = function() {

        window.location.href =
            "?id=ticket_history";

    };


    // =====================================
    // FEEDBACK
    // =====================================

    c.feedback = function() {

        window.location.href =
            "?id=student_feedback";

    };

};

sp_widget.css:
/* =========================================
   STUDENT DASHBOARD
========================================= */

.student-dashboard {
    width: 100%;
    min-height: 100vh;
    background: #f3f6fa;
    color: #07182c;
    font-family: "Segoe UI", Arial, sans-serif;
}


/* =========================================
   HEADER
========================================= */

.dashboard-header {
    height: 68px;
    background: #ffffff;
    border-bottom: 1px solid #dce3ea;

    display: flex;
    align-items: center;
    justify-content: space-between;

    padding: 0 36px;
}


.welcome-title {
    font-size: 25px;
    font-weight: 700;
    color: #07182c;
}


.student-profile {
    display: flex;
    align-items: center;
    gap: 12px;
}


.student-name {
    font-size: 16px;
    color: #53677d;
}


.student-badge {
    background: #2767df;
    color: #ffffff;

    padding: 7px 14px;

    border-radius: 18px;

    font-size: 12px;
    font-weight: 700;
    letter-spacing: .4px;
}


/* =========================================
   MAIN CONTENT
========================================= */

.dashboard-content {
    padding: 30px 36px 60px;
}


/* =========================================
   WELCOME BANNER
========================================= */

.welcome-banner {

    min-height: 170px;

    background:
        linear-gradient(
            110deg,
            #159c91,
            #117a73
        );

    border-radius: 18px;

    padding: 28px 36px;

    color: #ffffff;

    box-sizing: border-box;

    margin-bottom: 25px;

    box-shadow:
        0 8px 22px rgba(0, 90, 90, .12);
}


.welcome-banner h1 {

    margin: 0 0 8px;

    font-size: 30px;
    font-weight: 750;
}


.welcome-banner p {

    margin: 0 0 5px;

    font-size: 17px;

    line-height: 1.6;
}


.activity-count {

    font-size: 17px;

    margin-top: 2px;
}


.activity-count strong {
    font-weight: 800;
}


.separator {

    margin: 0 8px;

    opacity: .9;
}


/* =========================================
   THREE COMPONENT GRID
========================================= */

.component-grid {

    display: grid;

    grid-template-columns:
        repeat(3, 1fr);

    gap: 20px;
}


/* =========================================
   CARDS
========================================= */

.dashboard-card {

    background: #ffffff;

    border: 1px solid #dbe3eb;

    border-radius: 18px;

    min-height: 150px;

    padding: 27px;

    box-sizing: border-box;

    cursor: pointer;

    position: relative;

    transition:
        transform .2s ease,
        box-shadow .2s ease,
        border-color .2s ease;
}


.dashboard-card:hover {

    transform: translateY(-4px);

    box-shadow:
        0 10px 25px rgba(23, 45, 70, .10);

    border-color: #b8c8d9;
}


/* =========================================
   CARD TITLE
========================================= */

.card-title {

    display: flex;

    align-items: center;

    gap: 10px;

    font-size: 21px;

    font-weight: 750;

    color: #07182c;

    margin-bottom: 18px;
}


.card-icon {

    font-size: 22px;

    width: 27px;

    display: inline-flex;

    align-items: center;

    justify-content: center;
}


/* =========================================
   CARD DESCRIPTION
========================================= */

.dashboard-card p {

    margin: 0;

    color: #59708a;

    font-size: 16px;

    line-height: 1.65;

    max-width: 480px;
}


/* =========================================
   CARD ACTION
========================================= */

.card-action {

    margin-top: 18px;

    font-size: 14px;

    font-weight: 700;

    color: #087e72;

    opacity: 0;

    transform: translateY(4px);

    transition: .2s;
}


.dashboard-card:hover .card-action {

    opacity: 1;

    transform: translateY(0);
}


/* =========================================
   INDIVIDUAL CARD ACCENTS
========================================= */

.ticket-card:hover {
    border-top: 3px solid #159c91;
}


.history-card:hover {
    border-top: 3px solid #2767df;
}


.feedback-card:hover {
    border-top: 3px solid #f1b400;
}


/* =========================================
   MESSAGE
========================================= */

.dashboard-message {

    margin-top: 20px;

    padding: 13px 18px;

    background: #ffffff;

    border: 1px solid #dce4eb;

    border-radius: 10px;

    color: #52687d;

    text-align: center;
}


/* =========================================
   RESPONSIVE
========================================= */

@media screen and (max-width: 900px) {

    .component-grid {

        grid-template-columns:
            1fr;

    }

}


@media screen and (max-width: 600px) {

    .dashboard-header {

        padding: 0 18px;

    }


    .dashboard-content {

        padding: 20px 18px 40px;

    }


    .welcome-banner {

        padding: 24px;

    }


    .welcome-banner h1 {

        font-size: 25px;

    }


    .welcome-banner p {

        font-size: 15px;

    }


    .student-name {

        display: none;

    }

}

sp_widget.script:
(function() {

    /*
     * Default values
     */

    data.student_name = "Rahul Sharma";

    data.ticket_count = 0;

    data.feedback_count = 0;


    /*
     * Get logged-in user
     */

    if (gs.getUserID()) {

        var userGR = new GlideRecord("sys_user");

        if (userGR.get(gs.getUserID())) {

            data.student_name =
                userGR.getDisplayValue("name");

        }

    }


    /*
     * -----------------------------------
     * TICKET COUNT
     * -----------------------------------
     *
     * Change the table name and field
     * according to your ticket table.
     */

    var ticketGR = new GlideRecord("incident");

    ticketGR.addQuery("caller_id", gs.getUserID());

    ticketGR.query();

    data.ticket_count = ticketGR.getRowCount();


    /*
     * -----------------------------------
     * FEEDBACK COUNT
     * -----------------------------------
     *
     * Replace this table with your
     * actual feedback table.
     */

    var feedbackGR =
        new GlideRecord("u_cfms_feedback");

    if (feedbackGR.isValid()) {

        feedbackGR.addQuery(
            "u_student",
            gs.getUserID()
        );

        feedbackGR.query();

        data.feedback_count =
            feedbackGR.getRowCount();

    }


})();
